pid_t child_pid;
int status;

child_pid = fork();

if (child_pid == 0) {
    /* Child performs work */
    _exit(0);
}

if (child_pid > 0) {
    // Parent waits for any child to terminate
    pid_t terminated_pid = wait(&status);

    if (terminated_pid != -1) {
        // Status checks
        if (WIFEXITED(status)) {
            int exit_code = WEXITSTATUS(status);
        } else if (WIFSIGNALED(status)) {
            int sig = WTERMSIG(status);
        }
    }
}
